-- Shipped as its own addon so the ladder can be republished without reshipping
-- the code: this file was half of every ArenaPlus release.
--
-- Two addons cannot see each other's namespace, so the tables go on a global
-- and ArenaPlus copies them across as it loads. Same reason ArenaPlusAPI is a
-- global -- see the note above it in ArenaPlus\Core.lua.
--
-- The local keeps its name so the generated body below needs no changes.
ArenaPlusData = ArenaPlusData or {}
local ns = ArenaPlusData

-- Arena ladders, written by tools\UpdateFromBlizzard.ps1 from Blizzard's own
-- API. Do not edit by hand: rerun the script to refresh.
--
-- Down to the challenger cutoff, which is the last real title -- below it the API
-- publishes people on 96 rating who played one game and lost -- and, below
-- it, anyone with 20 games this season.
--
-- No class or spec: the leaderboard endpoint carries neither.
--
-- Region eu, season 14, read 2026-10-18 09:00 AM.
-- Realm display names, because the ladder only carries slugs and no rule
-- turns one back into the other: raden is Ra-den, lei-shen is Lei Shen and
-- arugal-au is Arugal (AU). Read from Blizzard's realm index; a slug with no
-- entry here is shown as it always was.
ns.REALM_NAMES = ns.REALM_NAMES or {}
for slug, name in pairs({
	["mirage-raceway"]="Mirage Raceway",
	["ook-ook"]="Ook Ook",
	["pyrewood-village"]="Pyrewood Village",
	["shekzeer"]="Shek'zeer",
}) do ns.REALM_NAMES[slug] = name end

